20	// addControlPlaneFlags registers the persistent flags shared by every
21	// control-plane command group. Persistent so they're inherited by nested
22	// subcommands (e.g. `entire repo mirror list`):
23	//   - --json: emit the raw wire JSON instead of the default human table.
24	//   - --insecure-http-auth: permit the token exchange over plain http://
25	//     (local/dev deployments where the core isn't behind TLS). Hidden, as
26	//     elsewhere in the CLI.
27	func addControlPlaneFlags(cmd *cobra.Command) {
28		cmd.PersistentFlags().Bool("json", false, "output raw JSON instead of a table")
29		cmd.PersistentFlags().Bool("insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
30		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
31			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
32		}
33	}
