35	// jsonRequested reports whether --json was set on cmd or an ancestor. A
36	// lookup error means the flag isn't defined on this command tree, which is
37	// treated as "not requested".
38	func jsonRequested(cmd *cobra.Command) bool {
39		v, err := cmd.Flags().GetBool("json")
40		return err == nil && v
41	}
42	
43	// insecureHTTPRequested reports whether --insecure-http-auth was set on cmd
44	// or an ancestor.
45	func insecureHTTPRequested(cmd *cobra.Command) bool {
46		v, err := cmd.Flags().GetBool("insecure-http-auth")
47		return err == nil && v
48	}
