50	// addForceFlag registers the standard confirmation bypass on a destructive
51	// control-plane command: --force/-f, with --yes/-y as an alias. Either skips
52	// the prompt. Read the combined value with forceRequested.
53	func addForceFlag(cmd *cobra.Command) {
54		cmd.Flags().BoolP("force", "f", false, "Skip the confirmation prompt")
55		cmd.Flags().BoolP("yes", "y", false, "Skip the confirmation prompt (alias for --force)")
56	}
