58	// forceRequested reports whether the delete should skip its confirmation
59	// prompt, i.e. --force or its --yes alias was set.
60	func forceRequested(cmd *cobra.Command) bool {
61		force, ferr := cmd.Flags().GetBool("force")
62		yes, yerr := cmd.Flags().GetBool("yes")
63		return (ferr == nil && force) || (yerr == nil && yes)
64	}
