66	// runControlPlaneDelete is the shared body of the destructive `delete` verbs
67	// (org/project/repo). It resolves the target ref to a ULID, gates on a
68	// confirmation prompt (bypassed by --force/--yes), deletes, and reports the
69	// resolved identifier. noun names the resource ("org"); ref is the user's
70	// original argument, shown alongside the resolved ULID. resolve and del isolate
71	// the per-resource API calls.
72	func runControlPlaneDelete(
73		cmd *cobra.Command,
74		noun, ref string,
75		resolve func(context.Context, *coreapi.Client) (string, error),
76		del func(context.Context, *coreapi.Client, string) error,
77	) error {
78		force := forceRequested(cmd)
79		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
80			id, err := resolve(ctx, c)
81			if err != nil {
82				return err
83			}
84			label := noun + " " + resolvedRefLabel(ref, id)
85			proceed, err := confirmControlPlaneDeletion(ctx, cmd.OutOrStdout(), label, force, interactive.CanPromptInteractively())
86			if err != nil {
87				return err
88			}
89			if !proceed {
90				return nil
91			}
92			if err := del(ctx, c, id); err != nil {
93				// Idempotent delete: a resource that's already gone (a 404 from the
94				// delete call — e.g. a ULID passed straight through, or a concurrent
95				// delete) is the desired end state, not an error.
96				if isCoreNotFound(err) {
97					cmd.Printf("%s not found; nothing to delete\n", label)
98					return nil
99				}
100				return err
101			}
102			cmd.Printf("Deleted %s\n", label)
103			return nil
104		})
105	}
106	
107	// confirmControlPlaneDeletion gates a destructive control-plane delete. With
108	// force it proceeds silently. Otherwise it requires an interactive terminal:
109	// with none it refuses (returns an error) rather than deleting unprompted; with
110	// one it shows a confirmation form. canPrompt is passed in (not queried) so the
111	// decision is unit-testable without a TTY. label is the human description of
112	// the target, e.g. `org acme (01J…)`.
113	func confirmControlPlaneDeletion(ctx context.Context, w io.Writer, label string, force, canPrompt bool) (bool, error) {
114		if force {
115			return true, nil
116		}
117		if !canPrompt {
118			return false, fmt.Errorf("refusing to delete %s without confirmation; pass --force", label)
119		}
120		// huh opens the TTY during form startup regardless of context state, so
121		// guard explicitly to honor an already-cancelled command context.
122		if ctx.Err() != nil {
123			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
124		}
125		confirmed := false
126		form := NewAccessibleForm(
127			huh.NewGroup(huh.NewConfirm().Title(fmt.Sprintf("Delete %s?", label)).Value(&confirmed)),
128		)
129		if err := form.RunWithContext(ctx); err != nil {
130			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
131			// an error — mirror confirmTrailDeletion.
132			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
133				return false, nil
134			}
135			return false, fmt.Errorf("deletion prompt: %w", err)
136		}
137		if !confirmed {
138			fmt.Fprintln(w, "Deletion cancelled.")
139			return false, nil
140		}
141		return true, nil
142	}
