207	// runCoreObject fetches a single value via fn and renders it as a vertical
208	// field/value list (default) or raw JSON (--json), reusing the same column
209	// definition as the matching list view.
210	func runCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
211		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
212			item, err := fn(ctx, c)
213			if err != nil {
214				return err
215			}
216			if jsonRequested(cmd) {
217				return printJSON(cmd.OutOrStdout(), item)
218			}
219			return printFields(cmd.OutOrStdout(), headers, row(*item))
220		})
221	}
