223	// tableStyles holds the foreground styles for the human table/field views,
224	// matching the activity/session palette: gray ("8") for headers and
225	// secondary cells, white ("7") for the primary (first-column) value. When
226	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
227	// styles are no-ops and output is plain.
228	type tableStyles struct {
229		enabled bool
230		header  lipgloss.Style
231		primary lipgloss.Style
232		cell    lipgloss.Style
233	}
234	
235	func newTableStyles(w io.Writer) tableStyles {
236		if !shouldUseColor(w) {
237			return tableStyles{}
238		}
239		return tableStyles{
240			enabled: true,
241			header:  lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true),
242			primary: lipgloss.NewStyle().Foreground(lipgloss.Color("7")),
243			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
244		}
245	}
246	
247	// style applies s to text only when color is enabled; otherwise it returns
248	// text unchanged so padding math and plain output stay correct.
249	func (t tableStyles) style(s lipgloss.Style, text string) string {
250		if !t.enabled {
251			return text
252		}
253		return s.Render(text)
254	}
255	
256	// columnStyle picks the foreground for a data cell: the first column is the
257	// primary identifier (white), the rest are secondary (gray).
258	func (t tableStyles) columnStyle(col int) lipgloss.Style {
259		if col == 0 {
260			return t.primary
261		}
262		return t.cell
263	}
264	
265	// printTable writes headers plus one row per item, columns aligned on the
266	// plain-text widths so ANSI color codes don't throw off the layout (they're
267	// applied after padding). Callers handle the empty case.
268	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
269		st := newTableStyles(w)
270		rows := make([][]string, len(items))
271		for i, it := range items {
272			rows[i] = row(it)
273		}
274		widths := columnWidths(headers, rows)
275	
276		var b strings.Builder
277		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
278		for _, r := range rows {
279			writeTableRow(&b, r, widths, st.columnStyle, st)
280		}
281		if _, err := io.WriteString(w, b.String()); err != nil {
282			return fmt.Errorf("render table: %w", err)
283		}
284		return nil
285	}
286	
287	// printFields writes a single record as aligned "FIELD  value" lines: the
288	// label in header gray, the value in the same primary/secondary color the
289	// list view would give that column.
290	func printFields(w io.Writer, headers, values []string) error {
291		st := newTableStyles(w)
292		labelWidth := 0
293		for _, h := range headers {
294			if n := lipgloss.Width(h); n > labelWidth {
295				labelWidth = n
296			}
297		}
298		var b strings.Builder
299		for i, h := range headers {
300			var v string
301			if i < len(values) {
302				v = values[i]
303			}
304			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
305			b.WriteString(label)
306			b.WriteString("  ")
307			b.WriteString(st.style(st.columnStyle(i), v))
308			b.WriteByte('\n')
309		}
310		if _, err := io.WriteString(w, b.String()); err != nil {
311			return fmt.Errorf("render fields: %w", err)
312		}
313		return nil
314	}
315	
316	// columnWidths returns the max plain-text width of each column across the
317	// headers and all rows.
318	func columnWidths(headers []string, rows [][]string) []int {
319		widths := make([]int, len(headers))
320		for i, h := range headers {
321			widths[i] = lipgloss.Width(h)
322		}
323		for _, r := range rows {
324			for i, c := range r {
325				if i < len(widths) && lipgloss.Width(c) > widths[i] {
326					widths[i] = lipgloss.Width(c)
327				}
328			}
329		}
330		return widths
331	}
332	
333	// writeTableRow pads each cell to its column width on the plain text, then
334	// styles it — so alignment is computed before any ANSI codes are added.
335	// The final column isn't padded, avoiding trailing whitespace.
336	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
337		for i, c := range cells {
338			last := i == len(cells)-1
339			padded := c
340			if !last && i < len(widths) {
341				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
342			}
343			b.WriteString(st.style(styleFor(i), padded))
344			if !last {
345				b.WriteString("  ")
346			}
347		}
348		b.WriteByte('\n')
349	}
350	
351	// runCoreJSON runs fn against an authenticated control-plane client and
352	// prints its result as indented JSON. It owns the preamble every
353	// control-plane command shares: silence usage so input errors don't spam
354	// the usage block, build the client, and map an API error to a
355	// problem-detail SilentError. Commands supply only the call + the value to
356	// render.
357	func runCoreJSON(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) (any, error)) error {
358		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
359			out, err := fn(ctx, c)
360			if err != nil {
361				return err
362			}
363			return printJSON(cmd.OutOrStdout(), out)
364		})
365	}
366	
367	// activeCoreClient builds the control-plane client for active-context
368	// commands. A package-level seam (production wiring is coreapi.New) so
369	// command-level tests can point the whole command tree at an httptest server
370	// without standing up the auth/context/TLS stack.
371	var activeCoreClient = func(context.Context) (*coreapi.Client, error) { return coreapi.New() }
372	
373	// runCore is the variant for commands that don't render JSON (delete,
374	// revoke, remove): it runs the same preamble — silence usage, build
375	// client, map API errors — and leaves any success output to fn. The client
376	// dials the active context's core (coreapi.New); use runCoreForCluster for
377	// commands addressed at a specific cluster.
378	func runCore(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) error) error {
379		return runCoreClient(cmd, activeCoreClient, fn)
380	}
381	
382	// runCoreForCluster is runCore for resource-provider commands addressed at a
383	// specific cluster (mirror create/remove, mirror collaborators list):
384	// it dials the core that fronts clusterHost — discovered from the cluster's
385	// /.well-known/entire-cluster.json, authenticating with the matching local
386	// context — instead of the active context. So the command works on a cluster in
387	// a federation other than the active login, instead of failing with "unknown
388	// cluster_host". See coreapi.NewForCluster.
389	func runCoreForCluster(cmd *cobra.Command, clusterHost string, fn func(ctx context.Context, c *coreapi.Client) error) error {
390		return runCoreClient(cmd, func(ctx context.Context) (*coreapi.Client, error) {
391			return coreapi.NewForCluster(ctx, clusterHost)
392		}, fn)
393	}
394	
395	// runCoreClient owns the control-plane preamble shared by the active-context
396	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
397	// opt into plain-HTTP token exchange if requested, build the client via
398	// newClient, run fn, and map API errors. The only difference between the two
399	// variants is which core newClient dials.
400	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
401		cmd.SilenceUsage = true
402		// Opt into plain-HTTP token exchange before the client (and its lazily
403		// built token manager) is constructed — the manager freezes the
404		// setting on first use.
405		if insecureHTTPRequested(cmd) {
406			auth.EnableInsecureHTTP()
407		}
408		client, err := newClient(cmd.Context())
409		if err != nil {
410			return fmt.Errorf("connect to Entire control plane: %w", err)
411		}
412		if err := fn(cmd.Context(), client); err != nil {
413			return renderCoreError(err)
414		}
415		return nil
416	}
417	
418	// markRequired marks one or more flags required, panicking if a name
419	// doesn't exist — that can only happen from a typo at wiring time, never
420	// at runtime, so a panic surfaces the bug immediately rather than letting
421	// a "required" flag silently not be enforced.
422	func markRequired(cmd *cobra.Command, names ...string) {
423		for _, name := range names {
424			if err := cmd.MarkFlagRequired(name); err != nil {
425				panic(fmt.Sprintf("mark flag %q required: %v", name, err))
426			}
427		}
428	}
429	
430	// renderCoreError converts a Core API error into the server's
431	// problem-detail message (so users see "organization name already taken"
432	// rather than ogen's decode-wrapped string), falling back to the raw error
433	// for transport/local failures. It returns a plain error, not a
434	// SilentError: main.go prints plain errors, and runCore has already set
435	// SilenceUsage, so the message reaches the user without a usage dump. (A
436	// SilentError here would be swallowed — main.go skips printing those —
437	// leaving e.g. a 409 conflict with no output.)
438	func renderCoreError(err error) error {
439		if err == nil {
440			return nil
441		}
442		if msg := coreapi.APIError(err); msg != "" {
443			return errors.New(msg)
444		}
445		return err
446	}
447	
448	// printJSON writes v as indented JSON to w — the --json view for list/get
449	// and the default for create commands that echo the new object.
450	func printJSON(w io.Writer, v any) error {
451		enc := json.NewEncoder(w)
452		enc.SetIndent("", "  ")
453		if err := enc.Encode(v); err != nil {
454			return fmt.Errorf("encode output: %w", err)
455		}
456		return nil
457	}
