12	
13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID. A ULID is always passed straight through with no
18	// network call. A name is resolved by the control plane's O(1), case-insensitive
19	// by-name lookup (the server matches on lower(name) and returns the single match
20	// under the response's singular `org`/`project` field, or 404) — the CLI never
21	// lists everything and filters client-side.
22	
23	// providerGitHub is the identity-provider slug for GitHub-backed accounts, the
24	// provider half of a qualified grantee handle like "github:alice". GitHub is the
25	// only provider with backing accounts today; other slugs resolve once they exist
26	// server-side. (Distinct from setup.go's checkpointProviderGitHub, which names
27	// the checkpoint hosting provider — same string, unrelated concern.)
28	const providerGitHub = "github"
29	
30	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
31	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
32	// The check is shape-only and case-insensitive on the alphabet; it never hits
33	// the network. A name that happened to be 26 valid base32 characters would be
34	// misread as an id, but real org/project names don't take that form, and the
35	// user can always fall back to the explicit ULID.
36	func looksLikeULID(s string) bool {
37		if len(s) != 26 {
38			return false
39		}
40		for _, r := range strings.ToUpper(s) {
41			switch {
42			case r >= '0' && r <= '9':
43			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
44			default:
45				return false
46			}
47		}
48		return true
49	}
50	
51	// isCoreNotFound reports whether err is a control-plane 404. The by-name lookups
52	// (ListOrgs/ListProjects/ListOrgProjects with ?name=) return 404 when nothing
53	// matches; callers turn that into a friendly "no X named" message.
54	func isCoreNotFound(err error) bool {
55		var se *coreapi.ErrorModelStatusCode
56		return errors.As(err, &se) && se.StatusCode == http.StatusNotFound
57	}
58	
59	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
60	// returned unchanged; a name is resolved via the server's case-insensitive
61	// by-name lookup.
62	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
63		if looksLikeULID(ref) {
64			return ref, nil
65		}
66		out, err := c.ListOrgs(ctx, coreapi.ListOrgsParams{Name: coreapi.NewOptString(ref)})
67		if err != nil {
68			if isCoreNotFound(err) {
69				return "", noOrgNamedErr(ref)
70			}
71			return "", err
72		}
73		org, ok := out.Org.Get()
74		if !ok {
75			return "", noOrgNamedErr(ref)
76		}
77		return org.ID, nil
78	}
79	
80	// resolveAccountRef turns an account reference into its ULID. A ULID passes
81	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
82	// "github:alice") resolved via the control plane. We support github-backed
83	// user accounts today; other providers will resolve once they exist server-side.
84	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
85		if looksLikeULID(ref) {
86			return ref, nil
87		}
88		provider, handle, err := parseQualifiedHandle(ref)
89		if err != nil {
90			return "", err
91		}
92		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
93		if err != nil {
94			return "", err
95		}
96		// ResolvedIdentity.AccountId is a plain string, so a handle that resolves to
97		// an identity with no backing account would silently forward "" as the owner
98		// ULID and fail later with an opaque server-side create error. Catch it here.
99		if id.AccountId == "" {
100			return "", fmt.Errorf("handle %q resolved to no account", ref)
101		}
102		return id.AccountId, nil
103	}
104	
105	// resolveGranteeProvider turns a grantee reference into the (provider,
106	// providerUserId) pair the grant/membership "by provider" routes key on. The
107	// reference is a provider-qualified handle (e.g. "github:alice"); it is
108	// resolved through the control plane to the provider's stable numeric user id.
109	// The friendly handle alone is not what the grant routes accept — passing it as
110	// --provider-user-id was the COR-699 footgun ("provider identity not found") —
111	// so the CLI always resolves it first. A bare account ULID is rejected here:
112	// the by-provider routes can't be addressed by ULID, and there is no reverse
113	// account→provider-id lookup; callers that accept a ULID grantee (project/repo
114	// remove) handle it via the typed-id route before reaching this helper.
115	func resolveGranteeProvider(ctx context.Context, c *coreapi.Client, ref string) (provider, providerUserID string, err error) {
116		// A ULID is a tempting paste from `grant … list` (which prints the grantee
117		// ID), but the by-provider routes can't be addressed by ULID. Reject it with
118		// a message that points at the form this command actually wants, rather than
119		// letting parseQualifiedHandle dangle a "(or a ULID)" hint that doesn't apply.
120		if looksLikeULID(ref) {
121			return "", "", fmt.Errorf("grantee %q is an account ULID; this command needs a provider-qualified handle like \"github:alice\"", ref)
122		}
123		p, handle, err := parseQualifiedHandle(ref)
124		if err != nil {
125			return "", "", err
126		}
127		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: p, Handle: handle})
128		if err != nil {
129			if isCoreNotFound(err) {
130				return "", "", fmt.Errorf("no %s identity for handle %q", p, handle)
131			}
132			return "", "", err
133		}
134		if id.ProviderUserId == "" {
135			return "", "", fmt.Errorf("handle %q resolved to no provider user id", ref)
136		}
137		// Prefer the server-normalized provider over the raw prefix, falling back to
138		// the input when the response omits it.
139		if id.Provider != "" {
140			p = id.Provider
141		}
142		return p, id.ProviderUserId, nil
143	}
144	
145	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
146	// into its provider ("github") and handle ("alice"). Accounts are addressed by
147	// this friendly form; a value with no "provider:" prefix is rejected so the
148	// user gets a clear hint rather than a confusing lookup miss.
149	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
150		provider, handle, ok := strings.Cut(ref, ":")
151		if !ok || provider == "" || handle == "" {
152			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
153		}
154		return provider, handle, nil
155	}
156	
157	// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
158	// ULID is returned unchanged; a name is resolved via the server's
159	// case-insensitive by-name lookup (the same call `entire project list --name`
160	// uses). Project names are globally unique, so a name maps to at most one project.
161	func resolveProjectRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
162		if looksLikeULID(ref) {
163			return ref, nil
164		}
165		out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(ref)})
166		if err != nil {
167			if isCoreNotFound(err) {
168				return "", noProjectNamedErr(ref)
169			}
170			return "", err
171		}
172		project, ok := out.Project.Get()
173		if !ok {
174			return "", noProjectNamedErr(ref)
175		}
176		return project.ID, nil
177	}
178	
179	// resolveRepoRef turns a repo reference into its ULID. A ULID passes through.
180	// A name requires a project scope (projectRef, itself a name or ULID) because
181	// repo names are unique only within a project: the repo is resolved via the
182	// server's case-insensitive by-name lookup, scoped to that project. Like the
183	// org/project endpoints, a name-filtered list returns the single match under the
184	// response's singular `repo` field (the plural `repos` is only populated for an
185	// unfiltered page) — reading `repos` here was the COR-699 bug.
186	func resolveRepoRef(ctx context.Context, c *coreapi.Client, ref, projectRef string) (string, error) {
187		if looksLikeULID(ref) {
188			return ref, nil
189		}
190		if projectRef == "" {
191			return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
192		}
193		projID, err := resolveProjectRef(ctx, c, projectRef)
194		if err != nil {
195			return "", err
196		}
197		out, err := c.ListProjectRepos(ctx, coreapi.ListProjectReposParams{ProjectId: projID, Name: coreapi.NewOptString(ref)})
198		if err != nil {
