200				return "", noRepoNamedErr(ref)
201			}
202			return "", err
203		}
204		repo, ok := out.Repo.Get()
205		if !ok {
206			return "", noRepoNamedErr(ref)
207		}
208		return repo.ID, nil
209	}
210	
211	func noOrgNamedErr(name string) error {
212		return fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", name)
213	}
214	
215	func noProjectNamedErr(name string) error {
216		return fmt.Errorf("no project named %q (run `entire project list` to see names, or pass a ULID)", name)
