222	
223	// resolvedRefLabel formats a reference for a success message so it always
224	// names the resolved ULID. When the user passed a ULID (ref == id) it returns
225	// the id alone; when they passed a name it returns "name (id)" so the message
226	// is unambiguous in environments where names can be reused across orgs/projects.
227	func resolvedRefLabel(ref, id string) string {
