package cli

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"github.com/entireio/cli/internal/coreapi"
)

// Control-plane commands reference orgs and projects by their parent ULID in
// many places (repo create --project, project create --owner, grant org/project
// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
// name: looksLikeULID decides which form was given, and the resolveXRef helpers
// turn a name into its ULID. A ULID is always passed straight through with no
// network call. A name is resolved by the control plane's O(1), case-insensitive
// by-name lookup (the server matches on lower(name) and returns the single match
// under the response's singular `org`/`project` field, or 404) — the CLI never
// lists everything and filters client-side.

// providerGitHub is the identity-provider slug for GitHub-backed accounts, the
// provider half of a qualified grantee handle like "github:alice". GitHub is the
// only provider with backing accounts today; other slugs resolve once they exist
// server-side. (Distinct from setup.go's checkpointProviderGitHub, which names
// the checkpoint hosting provider — same string, unrelated concern.)
const providerGitHub = "github"

// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
// The check is shape-only and case-insensitive on the alphabet; it never hits
// the network. A name that happened to be 26 valid base32 characters would be
// misread as an id, but real org/project names don't take that form, and the
// user can always fall back to the explicit ULID.
func looksLikeULID(s string) bool {
	if len(s) != 26 {
		return false
	}
	for _, r := range strings.ToUpper(s) {
		switch {
		case r >= '0' && r <= '9':
		case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
		default:
			return false
		}
	}
	return true
}

// isCoreNotFound reports whether err is a control-plane 404. The by-name lookups
// (ListOrgs/ListProjects/ListOrgProjects with ?name=) return 404 when nothing
// matches; callers turn that into a friendly "no X named" message.
func isCoreNotFound(err error) bool {
	var se *coreapi.ErrorModelStatusCode
	return errors.As(err, &se) && se.StatusCode == http.StatusNotFound
}

// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
// returned unchanged; a name is resolved via the server's case-insensitive
// by-name lookup.
func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	out, err := c.ListOrgs(ctx, coreapi.ListOrgsParams{Name: coreapi.NewOptString(ref)})
	if err != nil {
		if isCoreNotFound(err) {
			return "", noOrgNamedErr(ref)
		}
		return "", err
	}
	org, ok := out.Org.Get()
	if !ok {
		return "", noOrgNamedErr(ref)
	}
	return org.ID, nil
}

// resolveAccountRef turns an account reference into its ULID. A ULID passes
// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
// "github:alice") resolved via the control plane. We support github-backed
// user accounts today; other providers will resolve once they exist server-side.
func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	provider, handle, err := parseQualifiedHandle(ref)
	if err != nil {
		return "", err
	}
	id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
	if err != nil {
		return "", err
	}
	// ResolvedIdentity.AccountId is a plain string, so a handle that resolves to
	// an identity with no backing account would silently forward "" as the owner
	// ULID and fail later with an opaque server-side create error. Catch it here.
	if id.AccountId == "" {
		return "", fmt.Errorf("handle %q resolved to no account", ref)
	}
	return id.AccountId, nil
}

// resolveGranteeProvider turns a grantee reference into the (provider,
// providerUserId) pair the grant/membership "by provider" routes key on. The
// reference is a provider-qualified handle (e.g. "github:alice"); it is
// resolved through the control plane to the provider's stable numeric user id.
// The friendly handle alone is not what the grant routes accept — passing it as
// --provider-user-id was the COR-699 footgun ("provider identity not found") —
// so the CLI always resolves it first. A bare account ULID is rejected here:
// the by-provider routes can't be addressed by ULID, and there is no reverse
// account→provider-id lookup; callers that accept a ULID grantee (project/repo
// remove) handle it via the typed-id route before reaching this helper.
func resolveGranteeProvider(ctx context.Context, c *coreapi.Client, ref string) (provider, providerUserID string, err error) {
	// A ULID is a tempting paste from `grant … list` (which prints the grantee
	// ID), but the by-provider routes can't be addressed by ULID. Reject it with
	// a message that points at the form this command actually wants, rather than
	// letting parseQualifiedHandle dangle a "(or a ULID)" hint that doesn't apply.
	if looksLikeULID(ref) {
		return "", "", fmt.Errorf("grantee %q is an account ULID; this command needs a provider-qualified handle like \"github:alice\"", ref)
	}
	p, handle, err := parseQualifiedHandle(ref)
	if err != nil {
		return "", "", err
	}
	id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: p, Handle: handle})
	if err != nil {
		if isCoreNotFound(err) {
			return "", "", fmt.Errorf("no %s identity for handle %q", p, handle)
		}
		return "", "", err
	}
	if id.ProviderUserId == "" {
		return "", "", fmt.Errorf("handle %q resolved to no provider user id", ref)
	}
	// Prefer the server-normalized provider over the raw prefix, falling back to
	// the input when the response omits it.
	if id.Provider != "" {
		p = id.Provider
	}
	return p, id.ProviderUserId, nil
}

// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
// into its provider ("github") and handle ("alice"). Accounts are addressed by
// this friendly form; a value with no "provider:" prefix is rejected so the
// user gets a clear hint rather than a confusing lookup miss.
func parseQualifiedHandle(ref string) (provider, handle string, err error) {
	provider, handle, ok := strings.Cut(ref, ":")
	if !ok || provider == "" || handle == "" {
		return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
	}
	return provider, handle, nil
}

// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
// ULID is returned unchanged; a name is resolved via the server's
// case-insensitive by-name lookup (the same call `entire project list --name`
// uses). Project names are globally unique, so a name maps to at most one project.
func resolveProjectRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(ref)})
	if err != nil {
		if isCoreNotFound(err) {
			return "", noProjectNamedErr(ref)
		}
		return "", err
	}
	project, ok := out.Project.Get()
	if !ok {
		return "", noProjectNamedErr(ref)
	}
	return project.ID, nil
}

// resolveRepoRef turns a repo reference into its ULID. A ULID passes through.
// A name requires a project scope (projectRef, itself a name or ULID) because
// repo names are unique only within a project: the repo is resolved via the
// server's case-insensitive by-name lookup, scoped to that project. Like the
// org/project endpoints, a name-filtered list returns the single match under the
// response's singular `repo` field (the plural `repos` is only populated for an
// unfiltered page) — reading `repos` here was the COR-699 bug.
func resolveRepoRef(ctx context.Context, c *coreapi.Client, ref, projectRef string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	if projectRef == "" {
		return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
	}
	projID, err := resolveProjectRef(ctx, c, projectRef)
	if err != nil {
		return "", err
	}
	out, err := c.ListProjectRepos(ctx, coreapi.ListProjectReposParams{ProjectId: projID, Name: coreapi.NewOptString(ref)})
	if err != nil {
		if isCoreNotFound(err) {
			return "", noRepoNamedErr(ref)
		}
		return "", err
	}
	repo, ok := out.Repo.Get()
	if !ok {
		return "", noRepoNamedErr(ref)
	}
	return repo.ID, nil
}

func noOrgNamedErr(name string) error {
	return fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", name)
}

func noProjectNamedErr(name string) error {
	return fmt.Errorf("no project named %q (run `entire project list` to see names, or pass a ULID)", name)
}

func noRepoNamedErr(name string) error {
	return fmt.Errorf("no repo named %q in that project (run `entire repo list <project>` to see names, or pass a ULID)", name)
}

// resolvedRefLabel formats a reference for a success message so it always
// names the resolved ULID. When the user passed a ULID (ref == id) it returns
// the id alone; when they passed a name it returns "name (id)" so the message
// is unambiguous in environments where names can be reused across orgs/projects.
func resolvedRefLabel(ref, id string) string {
	if ref == id {
		return id
	}
	return fmt.Sprintf("%s (%s)", ref, id)
}

// toProjectList adapts a name-filtered project response — which returns the
// single match under the response's singular `project` field — into a slice for
// list output (empty when the field is unset).
func toProjectList(p coreapi.OptProject) []coreapi.Project {
	if v, ok := p.Get(); ok {
		return []coreapi.Project{v}
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/url"
	"regexp"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/internal/coreapi"
)

// mirrorColumns is the human table/field view of a mirror: the scannable
// repo name, the clone URL you'd copy, and whether the upstream is
// private. The cluster is omitted — it's already embedded in the clone
// URL — and the wire model's internal ids are dropped entirely. The clone
// URL is synthesised from the mirror's coords (the form `git clone`
// accepts), since the list API doesn't return it.
var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}

func mirrorRow(m coreapi.Mirror) []string {
	repo := m.Owner + "/" + m.Repo
	cloneURL := mirrorCloneURL(m.ClusterHost, m.Owner, m.Repo)
	private := "no"
	if m.IsPrivate.Or(false) {
		private = "yes"
	}
	return []string{repo, cloneURL, private}
}

// availableMirrorColumns is the view of a repo you *could* mirror: the
// scannable repo name, your effective GitHub access, and whether it's
// onboardable. STATUS is "available" (run `entire repo mirror create` to
// onboard), "mirrored" (already done — `entire repo mirror list` shows the
// clone URL), or "owner-only" (a personal repo of another user; only its
// owner may mirror it). No clone URL column: an un-onboarded repo doesn't
// have one yet.
var availableMirrorColumns = []string{"REPO", "ACCESS", "STATUS"}

func availableMirrorRow(m coreapi.AvailableMirror) []string {
	return []string{m.Owner + "/" + m.Repo, string(m.Access), string(m.Status)}
}

// defaultClusterHost is the cluster the positional-arg mirror commands target
// when the caller omits the <cluster-host> argument. The no-arg create wizard
// instead enumerates real clusters from the catalog (GET /api/v1/clusters, see
// availableRegions in repo_mirror_create_wizard.go); this stays as the
// single-region fallback for the explicit `create <github-url>` form.
const defaultClusterHost = "aws-us-east-2.entire.io"

// clusterArg returns the cluster host from the optional second positional
// (after <github-url>), or defaultClusterHost when it was omitted.
func clusterArg(args []string) string {
	return clusterArgAt(args, 1)
}

// clusterArgAt returns the cluster host from the optional positional at idx,
// or defaultClusterHost when it was omitted. Commands with leading positionals
// (e.g. collaborators list <github-url> [cluster-host]) pass the trailing index.
func clusterArgAt(args []string, idx int) string {
	if len(args) > idx {
		return args[idx]
	}
	return defaultClusterHost
}

// clusterHostLabelRe matches one DNS label: alphanumeric, internal hyphens
// allowed, no leading/trailing hyphen.
var clusterHostLabelRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$`)

// validateClusterHost rejects a cluster host that is anything other than a
// bare DNS name or IP with an optional :port. The host is concatenated as
// "https://"+host into the clone URL and the STS audience
// (auth.RepoScopedToken), so a value carrying URL metacharacters can redirect
// the request — and the repo-scoped basic-auth token it carries — somewhere
// other than the intended cluster. Classic case:
// `aws-us-east-2.entire.io@evil.com`, which Go's URL parser reads as
// host=evil.com with the real cluster demoted to userinfo, leaking the token
// to evil.com. We parse the host the same way the rest of the code does and
// require it to round-trip to a bare host with no userinfo, path, query, or
// fragment, then confirm the hostname is a valid IP or DNS name. This is
// cheap client-side defense-in-depth and doesn't depend on the server's STS
// invalid_target canonicalization catching the trick.
func validateClusterHost(host string) error {
	if strings.TrimSpace(host) == "" {
		return errors.New("cluster host is empty")
	}
	u, err := url.Parse("https://" + host)
	if err != nil {
		return fmt.Errorf("%q is not a valid host", host)
	}
	if u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.Host != host {
		return fmt.Errorf("%q must be a bare host[:port] (no scheme, userinfo, path, query, or fragment)", host)
	}
	hostname := u.Hostname()
	if net.ParseIP(hostname) != nil {
		return nil
	}
	for _, label := range strings.Split(hostname, ".") {
		if !clusterHostLabelRe.MatchString(label) {
			return fmt.Errorf("%q is not a valid DNS name or IP", host)
		}
	}
	return nil
}

// newRepoMirrorCmd is the `entire repo mirror` subtree: manage EntireDB
// GitHub-mirror placements on a cluster. Mirrors the standalone entiredb
// CLI's `entire repo mirror` surface for the server-side half (create /
// list / get / remove). The local-clone rewrite (`mirror use`) is not
// ported — it's a git-config + git-remote-entire concern outside the
// control-plane API.
func newRepoMirrorCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "mirror",
		Short: "Manage GitHub-mirror placements on EntireDB clusters",
	}
	cmd.AddCommand(newRepoMirrorCreateCmd())
	cmd.AddCommand(newRepoMirrorListCmd())
	cmd.AddCommand(newRepoMirrorGetCmd())
	cmd.AddCommand(newRepoMirrorRemoveCmd())
	cmd.AddCommand(newRepoMirrorCollaboratorsCmd())
	return cmd
}

func newRepoMirrorCreateCmd() *cobra.Command {
	var (
		noWait      bool
		waitTimeout time.Duration
	)
	cmd := &cobra.Command{
		Use:   "create [github-url] [cluster-host]",
		Short: "Register a GitHub mirror on a cluster",
		Long: "With no arguments, launches an interactive wizard: pick repos to " +
			"mirror, pick one or more regions, then creates every (repo, region) " +
			"mirror in parallel and prints the clone URLs.\n\n" +
			"With a <github-url>, registers a mirror placement for that repo on " +
			"the target cluster, then waits for the initial GitHub→EntireDB clone " +
			"to finish so `git clone` works on return. Pass --no-wait to return " +
			"as soon as the placement is registered. Idempotent on " +
			"(upstream, cluster). The cluster-host defaults to " +
			defaultClusterHost + " when omitted (the interactive wizard, with " +
			"no args, instead lets you pick clusters).",
		Example: "  entire repo mirror create\n" +
			"  entire repo mirror create github.com/octocat/hello-world\n" +
			"  entire repo mirror create github.com/octocat/hello-world aws-us-east-2.entire.io",
		Args: cobra.RangeArgs(0, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return runMirrorCreateWizard(cmd, noWait, waitTimeout)
			}
			owner, repo, err := parseGitHubURL(args[0])
			if err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid <github-url>: %w", err)
			}
			// The non-interactive one-shot keeps a fixed default cluster
			// (defaultClusterHost) when [cluster-host] is omitted — catalog-based
			// cluster guessing is intentionally limited to the interactive
			// wizard (the no-args path above), so scripts get stable behavior.
			clusterHost := clusterArg(args)
			if err := validateClusterHost(clusterHost); err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid [cluster-host]: %w", err)
			}
			return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
				errW := cmd.ErrOrStderr()
				// Two-phase progress: a "Placing" spinner covers the fast
				// CreateMirror call (placement, <15s), then a separate "Cloning"
				// spinner covers the clone-readiness poll. An already-ready mirror
				// completes the first poll faster than the spinner's initial delay,
				// so the Cloning line never paints and we go straight to the clone
				// instructions.
				placing := startSpinner(errW, fmt.Sprintf("Placing mirror %s/%s into %s", owner, repo, clusterHost))
				placed := false
				var cloning func(success bool)
				// nil onStatus: the one-shot's spinners show liveness; the
				// per-mirror progress lines are the wizard's concern.
				outcome, err := createAndAwaitMirror(ctx, c, owner, repo, clusterHost, noWait, waitTimeout,
					func(created *coreapi.CreatedMirror) {
						placing(true)
						placed = true
						// Only start a Cloning spinner when there's a clone to await —
						// not for an empty upstream, and not for an admin-suspended
						// placement (which never becomes ready).
						if !noWait && !created.Empty && !created.Suspended {
							cloning = startSpinner(errW, fmt.Sprintf("Cloning %s/%s into %s", owner, repo, clusterHost))
						}
					}, nil)
				if !placed {
					// CreateMirror failed before onCreated fired — erase the line.
					placing(false)
				}
				if cloning != nil {
					// Only a confirmed-ready clone earns the ✓; everything else
					// (suspended, failed, timeout) erases the line and lets
					// reportOneShotMirror print the specific outcome.
					cloning(err == nil && outcome.polled && outcome.status == coreapi.MirrorStatusReady)
				}
				return reportOneShotMirror(cmd.OutOrStdout(), errW, outcome, err)
			})
		},
	}
	cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
	cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
	return cmd
}

// mirrorCreateOutcome bundles the create response with the clone status
// observed while waiting. polled is false for --no-wait and for empty upstreams,
// where there is nothing to await; in those cases status is unset.
type mirrorCreateOutcome struct {
	created *coreapi.CreatedMirror
	status  coreapi.MirrorStatus
	polled  bool
}

// createAndAwaitMirror is the single create-then-wait path shared by the
// `repo mirror create <github-url>` one-shot and the onboarding wizard, so both
// report identical lifecycle states. It registers the GitHub mirror on
// clusterHost (idempotent on (upstream, cluster)) and, unless noWait or the
// upstream is empty, polls the control plane until the clone reaches a terminal
// status. The returned error is the create error (when outcome.created is nil)
// or the wait error — a status sentinel (errMirrorCloneFailed /
// errMirrorSuspended) or a timeout; callers read outcome.status for the state.
//
// onCreated (may be nil) fires once the placement is registered, before any
// clone polling — it separates the fast "placing" phase from the slow "cloning"
// wait so callers can render them as distinct steps.
func createAndAwaitMirror(ctx context.Context, c *coreapi.Client, owner, repo, clusterHost string, noWait bool, timeout time.Duration, onCreated func(*coreapi.CreatedMirror), onStatus func(coreapi.MirrorStatus)) (mirrorCreateOutcome, error) {
	created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
		Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
		Owner:       owner,
		Repo:        repo,
		ClusterHost: clusterHost,
	})
	if err != nil {
		return mirrorCreateOutcome{}, err
	}
	if onCreated != nil {
		onCreated(created)
	}
	outcome := mirrorCreateOutcome{created: created}
	if created.Suspended {
		// The placement already existed and an admin has suspended it, so it
		// will never serve — skip the clone poll. The caller warns after echoing
		// the placement; a suspended re-create is still a (non-fatal) success,
		// so return no error.
		return outcome, nil
	}
	if created.Empty {
		// An empty upstream has nothing to clone, so don't poll for "ready" — it
		// never would. But an *existing* placement can be suspended even when
		// empty, and one status read surfaces that (a fresh create can't be
		// suspended — suspension follows upstream access loss). Mirrors the old
		// finishMirrorCreate behavior; the read is best-effort, so a transient
		// GetMirror error just falls through to the benign "nothing to clone".
		if !created.Created {
			if m, gerr := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: created.MirrorId}); gerr == nil {
				if s, ok := m.Status.Get(); ok && s == coreapi.MirrorStatusSuspended {
					outcome.status = s
					outcome.polled = true
					return outcome, errMirrorSuspended
				}
			}
		}
		return outcome, nil
	}
	if noWait {
		return outcome, nil
	}
	status, werr := awaitMirrorReady(ctx, c, created.MirrorId, timeout, onStatus)
	outcome.status = status
	outcome.polled = true
	return outcome, werr
}

// reportOneShotMirror renders the human output for `repo mirror create
// <github-url>` from the shared createAndAwaitMirror result. A nil
// outcome.created means CreateMirror itself failed — surface that error (nothing
// was printed yet). Otherwise echo the placement, then the lifecycle outcome.
func reportOneShotMirror(out, errW io.Writer, outcome mirrorCreateOutcome, err error) error {
	created := outcome.created
	if created == nil {
		return err
	}
	if created.Created {
		fmt.Fprintf(out, "\nRegistered mirror %s\n", created.MirrorId)
	} else {
		fmt.Fprintf(out, "\nMirror exists (%s)\n", created.MirrorId)
	}
	fmt.Fprintf(out, "  %s\n", created.MirrorUrl)

	if created.Suspended {
		// Echo the placement (above), warn, and exit non-zero: the mirror can't
		// be used, so a script chaining a clone shouldn't treat this as success.
		// SilentError keeps main.go from reprinting — the warning is the message.
		fmt.Fprintln(errW, "\nWARNING: this mirror has been suspended by an admin and won't be usable.")
		return NewSilentError(errMirrorSuspended)
	}

	if !outcome.polled {
		if created.Empty {
			fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
		} else {
			fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
		}
		return nil
	}

	switch outcome.status {
	case coreapi.MirrorStatusReady:
		fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
		return nil
	case coreapi.MirrorStatusSuspended:
		explainSuspendedMirror(errW, created.MirrorId)
		return NewSilentError(errMirrorSuspended)
	case coreapi.MirrorStatusFailed:
		return fmt.Errorf("initial clone of mirror %s failed", created.MirrorId)
	case coreapi.MirrorStatusProcessing:
		// Still processing when the poll returned: the wait timed out (or a
		// transport error broke the poll). awaitMirrorReady's err carries which.
		return err
	default:
		return err
	}
}

func newRepoMirrorListCmd() *cobra.Command {
	var cluster, provider, owner string
	var showAvailable bool
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if showAvailable {
				return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
					// Computed live from GitHub using your own login, so name the
					// core being dialled (same rationale as the existing-mirror
					// banner). --cluster/--provider don't apply here: the
					// onboardable set is cluster-agnostic and GitHub-only.
					if !jsonRequested(cmd) {
						fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
					}
					var params coreapi.ListAvailableMirrorsParams
					if owner != "" {
						params.Owner = coreapi.NewOptString(owner)
					}
					out, err := c.ListAvailableMirrors(ctx, params)
					if err != nil {
						return nil, err
					}
					return out.Available, nil
				})
			}
			return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
				// mirror list is identity-scoped: it shows the mirrors visible
				// from the active login's federation, so naming that login server
				// makes a surprising empty result legible — e.g. mirrors in a
				// different deployment than the active context (--cluster is a
				// filter, not a router). Name the core the client actually dials
				// (c.CoreOrigin) so the banner can never diverge from where the
				// request goes — in particular it reflects ENTIRE_TOKEN's aud,
				// which a separately-resolved ResolveControlPlaneTarget would miss.
				// On stderr so it never lands in a piped table; skipped for --json
				// to keep machine output clean.
				if !jsonRequested(cmd) {
					fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
				}
				return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
					params := coreapi.ListMirrorsParams{}
					if cluster != "" {
						params.Cluster = coreapi.NewOptString(cluster)
					}
					if provider != "" {
						params.Provider = coreapi.NewOptString(provider)
					}
					if owner != "" {
						params.Owner = coreapi.NewOptString(owner)
					}
					if cursor != "" {
						params.PageToken = coreapi.NewOptString(cursor)
					}
					out, err := c.ListMirrors(ctx, params)
					if err != nil {
						return nil, "", err
					}
					return out.Mirrors, out.NextPageToken.Or(""), nil
				})
			})
		},
	}
	cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
	cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
	cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
	cmd.Flags().BoolVar(&showAvailable, "show-available", false, "instead of existing mirrors, list GitHub repos you could onboard as mirrors (ignores --cluster/--provider)")
	return cmd
}

func newRepoMirrorGetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "get <mirror>",
		Short: "Show a mirror by ULID or clone URL",
		Long: "Show a mirror. <mirror> is either a mirror ULID or an entire:// clone " +
			"URL\n(entire://<cluster>/gh/<owner>/<repo>) — the form `mirror list` " +
			"prints and `git clone` accepts.",
		Example: "  entire repo mirror get 01KS6KFJR2XS6PZ188MVYE07AN\n" +
			"  entire repo mirror get entire://aws-us-east-2.entire.io/gh/octocat/hello-world",
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runCoreObject(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) (*coreapi.Mirror, error) {
				mirrorID, err := resolveMirrorRef(ctx, c, args[0])
				if err != nil {
					return nil, err
				}
				return c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: mirrorID})
			})
		},
	}
}

// resolveMirrorRef turns a mirror reference into its ULID. A ULID passes
// through unchanged. Otherwise the ref is parsed as an entire:// clone URL and
// resolved by listing the caller-visible mirrors for that (cluster, provider,
// owner) and matching the repo — there is no get-by-coords endpoint, only
// GetMirror(ULID). The clone URL carries the cluster, so the match is
// unambiguous even when the same upstream is mirrored on several clusters.
func resolveMirrorRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	clusterHost, provider, owner, repo, err := parseMirrorCloneURL(ref)
	if err != nil {
		return "", fmt.Errorf("%w; pass a mirror ULID or a clone URL (entire://<cluster>/gh/<owner>/<repo>)", err)
	}
	mirrors, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
		params := coreapi.ListMirrorsParams{
			Cluster:  coreapi.NewOptString(clusterHost),
			Provider: coreapi.NewOptString(provider),
			Owner:    coreapi.NewOptString(owner),
		}
		if cursor != "" {
			params.PageToken = coreapi.NewOptString(cursor)
		}
		out, lerr := c.ListMirrors(ctx, params)
		if lerr != nil {
			return nil, "", lerr
		}
		return out.Mirrors, out.NextPageToken.Or(""), nil
	})
	if err != nil {
		return "", err
	}
	// ListMirrors has no repo filter, so the owner-scoped page is matched on
	// repo client-side. Owner/repo are stored lowercase; EqualFold guards
	// against a differently-cased clone URL.
	for _, m := range mirrors {
		if strings.EqualFold(m.Repo, repo) {
			return m.MirrorId, nil
		}
	}
	return "", noMirrorErr(ref)
}

// parseMirrorCloneURL decomposes an entire:// mirror clone URL into its
// coordinates:
//
//	entire://<clusterHost>/gh/<owner>/<repo>
//
// Only the github ("gh") provider path is recognized — the only provider
// mirrors support today. The cluster host is validated the same way the
// create/remove verbs validate it, so a host carrying URL metacharacters is
// rejected at the boundary rather than flowing into the list filter.
func parseMirrorCloneURL(raw string) (clusterHost, provider, owner, repo string, err error) {
	u, perr := url.Parse(raw)
	if perr != nil || u.Scheme != "entire" {
		return "", "", "", "", fmt.Errorf("%q is not an entire:// clone URL", raw)
	}
	parts := strings.Split(strings.Trim(u.Path, "/"), "/")
	if len(parts) != 3 || parts[0] != "gh" {
		return "", "", "", "", fmt.Errorf("%q must be entire://<cluster>/gh/<owner>/<repo>", raw)
	}
	if verr := validateClusterHost(u.Host); verr != nil {
		return "", "", "", "", verr
	}
	// Trim a trailing .git so a URL pasted from `git remote -v` resolves the
	// same as the bare clone URL (matching gitremote.ParseURL). GitHub repo
	// names can contain dots, so only the suffix is trimmed, not all dots.
	repo = strings.ToLower(strings.TrimSuffix(parts[2], ".git"))
	return u.Host, string(coreapi.CreateMirrorInputBodyProviderGithub), strings.ToLower(parts[1]), repo, nil
}

func noMirrorErr(ref string) error {
	return fmt.Errorf("no mirror matching %q (run `entire repo mirror list` to see clone URLs, or pass a ULID)", ref)
}

func newRepoMirrorRemoveCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "remove <github-url> [cluster-host]",
		Short: "Un-register a GitHub mirror from a cluster",
		Long: "Removes a mirror placement for a GitHub repo from the target " +
			"cluster. Other clusters' placements of the same upstream are " +
			"unaffected. The cluster-host defaults to " + defaultClusterHost +
			" when omitted.",
		Example: "  entire repo mirror remove github.com/octocat/hello-world",
		Args:    cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			owner, repo, err := parseGitHubURL(args[0])
			if err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid <github-url>: %w", err)
			}
			clusterHost := clusterArg(args)
			if err := validateClusterHost(clusterHost); err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid [cluster-host]: %w", err)
			}
			return runCoreForCluster(cmd, clusterHost, func(ctx context.Context, c *coreapi.Client) error {
				// Delete by upstream coords in one call. A 404 is a real
				// error here, not idempotent success: the server only
				// answers 204 when it actually removed a placement, so a
				// 404 ("no such mirror / not visible / different cluster")
				// surfaces verbatim via renderCoreError rather than being
				// reported as a successful removal.
				if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
					Provider:    coreapi.DeleteMirrorProviderGithub,
					Owner:       owner,
					Repo:        repo,
					ClusterHost: clusterHost,
				}); err != nil {
					return err
				}
				cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
				return nil
			})
		},
	}
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"sort"
	"strings"

	"charm.land/huh/v2"
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/internal/coreapi"
)

// mirrorCloneRefRe parses the clone-ref shape `entire repo clone` accepts:
// the `/gh/<owner>/<repo>` path of a mirror's clone URL, with or without the
// leading slash. owner/repo reuse the GitHub identifier charsets from
// parseGitHubURL so the same metacharacter vectors are closed at the boundary
// (owner/repo flow unescaped into the synthesised entire:// clone URL).
var mirrorCloneRefRe = regexp.MustCompile(`^/?gh/` + gitHubOwnerPat + `/` + gitHubRepoPat + `$`)

// mirrorCloneProviderGitHub is the upstream provider the `gh` path token maps to
// — the value the control plane records and the list API filters on. Kept local
// to the clone path so the provider mapping is self-contained rather than
// borrowing a constant named for an unrelated (checkpoint) concern.
const mirrorCloneProviderGitHub = "github"

// entireCloneURLScheme is the scheme of a full mirror clone URL, which
// git-remote-entire resolves directly. Such a URL already names the cluster, so
// `repo clone` passes it through to `git clone` untouched.
const entireCloneURLScheme = "entire://"

// isEntireCloneURL reports whether ref is a full entire:// clone URL (vs. the
// `/gh/<owner>/<repo>` shorthand that needs a mirror lookup).
func isEntireCloneURL(ref string) bool {
	return strings.HasPrefix(strings.TrimSpace(ref), entireCloneURLScheme)
}

// mirrorCloneURL synthesizes the entire:// clone URL for a GitHub mirror from
// its cluster host and owner/repo — the form `git clone` accepts, which the
// mirror list API doesn't return. Shared by the mirror table view (mirrorRow)
// and `repo clone` so the wire format lives in one place.
func mirrorCloneURL(host, owner, repo string) string {
	return fmt.Sprintf("%s%s/gh/%s/%s", entireCloneURLScheme, host, owner, repo)
}

// parseMirrorCloneRef turns a clone ref like `/gh/entirehq/entire-api` into the
// API provider ("github") and the lowercased owner/repo. The `gh` token is the
// path provider used in entire:// clone URLs; it maps to the "github" upstream
// provider the control plane records.
func parseMirrorCloneRef(ref string) (provider, owner, repo string, err error) {
	m := mirrorCloneRefRe.FindStringSubmatch(strings.TrimSpace(ref))
	if m == nil {
		return "", "", "", fmt.Errorf("expected gh/<owner>/<repo> (leading slash optional), got %q", ref)
	}
	owner, repo = strings.ToLower(m[1]), strings.ToLower(m[2])
	if gitHubDotOnlyRe.MatchString(repo) {
		return "", "", "", fmt.Errorf("repo cannot be dot-only: %s", ref)
	}
	return mirrorCloneProviderGitHub, owner, repo, nil
}

func newRepoCloneCmd() *cobra.Command {
	var cluster string
	cmd := &cobra.Command{
		Use:   "clone <repo> [target-dir]",
		Short: "Clone a mirrored repository",
		Long: "Clone a GitHub mirror by its `/gh/<owner>/<repo>` ref, or by a full " +
			"`entire://<cluster>/gh/<owner>/<repo>` clone URL.\n\n" +
			"With a `/gh/<owner>/<repo>` ref, looks up where the repo is mirrored: if " +
			"it's on a single cluster, clones it directly; if it's mirrored on more " +
			"than one, prompts you to pick which to clone from (or pass --cluster to " +
			"choose non-interactively).\n\n" +
			"A full `entire://` URL already names the cluster, so it's passed straight " +
			"through to `git clone` with no lookup (and --cluster is ignored). The " +
			"optional [target-dir] is passed through to `git clone` either way.",
		Example: "  entire repo clone /gh/entirehq/entire-api\n" +
			"  entire repo clone /gh/entirehq/entire-api ./entire-api\n" +
			"  entire repo clone /gh/entirehq/entire-api --cluster aws-us-east-2.entire.io\n" +
			"  entire repo clone entire://aws-us-east-2.entire.io/gh/entirehq/entire-api",
		Args: cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			cmd.SilenceUsage = true
			// Trim once up front so the entire:// detection and the value forwarded
			// to git clone agree (the shorthand path trims inside parseMirrorCloneRef).
			ref := strings.TrimSpace(args[0])
			var targetDir string
			if len(args) > 1 {
				targetDir = args[1]
			}

			// A full entire:// clone URL already embeds the cluster host (it's what
			// --cluster would otherwise resolve to), so pass it verbatim to git clone
			// — no mirror lookup or cluster resolution. --cluster is irrelevant here.
			//
			// Deliberately NOT run through validateClusterHost: this is a raw URL the
			// user typed, forwarded to `git clone` exactly as given (the whole point
			// of this branch), so it's equivalent to running `git clone entire://…`
			// directly. The validateClusterHost guard applies on the shorthand path
			// where we *synthesize* the URL from a --cluster flag or an API-supplied
			// host — values that flow into the STS audience under our own construction.
			if isEntireCloneURL(ref) {
				return runGitClone(cmd.Context(), cmd, ref, targetDir)
			}

			provider, owner, repo, err := parseMirrorCloneRef(ref)
			if err != nil {
				return fmt.Errorf("invalid <repo>: %w", err)
			}

			var mirrors []coreapi.Mirror
			lister := func(ctx context.Context, c *coreapi.Client) error {
				ms, err := listMirrorsForRepo(ctx, c, provider, owner, repo)
				if err != nil {
					return err
				}
				mirrors = ms
				return nil
			}
			// An explicit --cluster may name a cluster in a different federation
			// than the active context, whose mirrors the active-context core can't
			// see (the original bug: cloning a royalcanin.partial.to mirror while a
			// different context is active failed with "not mirrored on ..."). Dial
			// the core fronting that cluster — discovered from its well-known and
			// authenticated with the matching local context, the same path
			// `mirror create <url> [cluster]` uses — so the lookup resolves against
			// the right federation. With no --cluster, list from the active context.
			runWithCore := runCore
			if cluster != "" {
				if err := validateClusterHost(cluster); err != nil {
					return fmt.Errorf("invalid --cluster: %w", err)
				}
				runWithCore = func(cmd *cobra.Command, fn func(context.Context, *coreapi.Client) error) error {
					return runCoreForCluster(cmd, cluster, fn)
				}
			}
			if err := runWithCore(cmd, lister); err != nil {
				return err
			}

			if len(mirrors) == 0 {
				return fmt.Errorf("no mirror found for /gh/%s/%s; run 'entire repo mirror create github.com/%s/%s' to onboard it", owner, repo, owner, repo)
			}

			chosen, err := selectCloneTarget(cmd, mirrors, cluster)
			if err != nil {
				return err
			}

			// chosen.ClusterHost is server-provided, but it's interpolated into the
			// entire:// clone URL just like the user-supplied --cluster, so apply the
			// same anti-token-leak guard (validateClusterHost) before building it —
			// defense-in-depth against a malformed host reaching git / the STS audience.
			if err := validateClusterHost(chosen.ClusterHost); err != nil {
				return fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
			}
			cloneURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
			return runGitClone(cmd.Context(), cmd, cloneURL, targetDir)
		},
	}
	cmd.Flags().StringVar(&cluster, "cluster", "", "cluster host to clone from when the repo is mirrored on more than one (may belong to another auth context)")
	return cmd
}

// mirrorLister is the subset of the control-plane client listMirrorsForRepo
// needs. Narrowing to an interface lets callers (e.g. the experts cell-target
// resolver) inject a fake control plane in tests; *coreapi.Client satisfies it.
type mirrorLister interface {
	ListMirrors(ctx context.Context, params coreapi.ListMirrorsParams) (*coreapi.ListMirrorsOutputBody, error)
}

// listMirrorsForRepo returns every mirror placement of one upstream repo across
// clusters. The list API filters by provider+owner server-side but has no repo
// filter, so the repo match is applied client-side (owner is already lowercased
// to match what the server persists).
func listMirrorsForRepo(ctx context.Context, c mirrorLister, provider, owner, repo string) ([]coreapi.Mirror, error) {
	all, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
		params := coreapi.ListMirrorsParams{
			Provider: coreapi.NewOptString(provider),
			Owner:    coreapi.NewOptString(owner),
		}
		if cursor != "" {
			params.PageToken = coreapi.NewOptString(cursor)
		}
		out, err := c.ListMirrors(ctx, params)
		if err != nil {
			return nil, "", fmt.Errorf("list mirrors: %w", err)
		}
		return out.Mirrors, out.NextPageToken.Or(""), nil
	})
	if err != nil {
		return nil, err
	}
	matched := make([]coreapi.Mirror, 0, len(all))
	for _, m := range all {
		if strings.EqualFold(m.Repo, repo) {
			matched = append(matched, m)
		}
	}
	return matched, nil
}

// selectCloneTarget resolves which mirror placement to clone from. With one
// placement it returns it directly. With --cluster it picks the matching one (or
// errors listing the available hosts). With more than one and no flag it prompts
// interactively, failing fast with a --cluster pointer when there's no terminal.
func selectCloneTarget(cmd *cobra.Command, mirrors []coreapi.Mirror, clusterFlag string) (coreapi.Mirror, error) {
	// Dedupe by cluster host: one placement per cluster is what a clone targets,
	// and the same host appearing twice would only confuse the picker. Key on the
	// case-folded host — DNS is case-insensitive, so a --cluster value differing
	// only in case from the API's ClusterHost must still match (the alternative is
	// a misleading "not mirrored on ..." after a successful lookup + dial).
	byHost := make(map[string]coreapi.Mirror, len(mirrors))
	hosts := make([]string, 0, len(mirrors))
	for _, m := range mirrors {
		key := strings.ToLower(m.ClusterHost)
		if _, seen := byHost[key]; seen {
			continue
		}
		byHost[key] = m
		hosts = append(hosts, key)
	}
	sort.Strings(hosts)

	if clusterFlag != "" {
		m, ok := byHost[strings.ToLower(strings.TrimSpace(clusterFlag))]
		if !ok {
			return coreapi.Mirror{}, fmt.Errorf("repo is not mirrored on %q; available: %s", clusterFlag, strings.Join(hosts, ", "))
		}
		return m, nil
	}

	if len(hosts) == 1 {
		return byHost[hosts[0]], nil
	}

	if !interactive.CanPromptInteractively() {
		return coreapi.Mirror{}, fmt.Errorf("repo is mirrored on %d clusters; pass --cluster to choose one of: %s", len(hosts), strings.Join(hosts, ", "))
	}

	options := make([]huh.Option[string], len(hosts))
	for i, h := range hosts {
		options[i] = huh.NewOption(mirrorCellLabel(byHost[h]), h)
	}
	var selected string
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("This repo is mirrored on more than one cluster — pick one to clone from").
				Options(options...).
				Value(&selected),
		),
	)
	if err := form.RunWithContext(cmd.Context()); err != nil {
		// handleFormCancellation prints "Clone cancelled." and returns nil for a
		// Ctrl+C / cancelled-context abort. Surface that as a SilentError so the
		// caller stops instead of falling through to clone a zero-value target
		// (the `entire:///gh/...` empty-host bug); a real form error propagates.
		if cerr := handleFormCancellation(cmd.ErrOrStderr(), "Clone", err); cerr != nil {
			return coreapi.Mirror{}, cerr
		}
		return coreapi.Mirror{}, NewSilentError(errors.New("clone cancelled"))
	}
	m, ok := byHost[selected]
	if !ok {
		return coreapi.Mirror{}, NewSilentError(errors.New("clone cancelled"))
	}
	return m, nil
}

// mirrorCellLabel is the human label for a mirror placement in the clone picker:
// the physical cell and jurisdiction when known, always anchored by the cluster
// host that goes into the clone URL.
func mirrorCellLabel(m coreapi.Mirror) string {
	cell := strings.TrimSpace(m.Cell.Or(""))
	jur := strings.TrimSpace(m.Jurisdiction.Or(""))
	switch {
	case cell != "" && jur != "":
		return fmt.Sprintf("%s (%s) — %s", cell, jur, m.ClusterHost)
	case cell != "":
		return fmt.Sprintf("%s — %s", cell, m.ClusterHost)
	default:
		return m.ClusterHost
	}
}

// runGitClone shells out to `git clone <cloneURL> [target-dir]`, wiring the
// child's stdio through so git-remote-entire's auth prompts and clone progress
// reach the user. A clone failure is wrapped as a SilentError: git already
// printed its own diagnostics, so main.go shouldn't reprint the wrapper.
func runGitClone(ctx context.Context, cmd *cobra.Command, cloneURL, targetDir string) error {
	args := []string{"clone", cloneURL}
	if targetDir != "" {
		args = append(args, targetDir)
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "Cloning %s\n", cloneURL)
	gitCmd := exec.CommandContext(ctx, "git", args...)
	gitCmd.Stdin = cmd.InOrStdin()
	gitCmd.Stdout = cmd.OutOrStdout()
	gitCmd.Stderr = cmd.ErrOrStderr()
	if err := gitCmd.Run(); err != nil {
		return NewSilentError(fmt.Errorf("git clone failed: %w", err))
	}
	return nil
}

package cli

import (
	"context"
	"fmt"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/internal/coreapi"
)

// mirrorCollaboratorColumns is the human table/field view of a mirror
// collaborator: the display handle, the reader/writer role, and the Entire
// account ULID (the stable identifier, shown last as the fallback when no
// handle resolves).
var mirrorCollaboratorColumns = []string{"HANDLE", "ROLE", "ACCOUNT"}

func mirrorCollaboratorRow(c coreapi.MirrorCollaborator) []string {
	handle := c.Handle.Or("")
	if handle == "" {
		handle = "-"
	}
	return []string{handle, c.Role, c.AccountId}
}

// newRepoMirrorCollaboratorsCmd wires `repo mirror collaborators list`: a
// read-only view of who can pull a mirror. It hits the user-facing
// GET /mirrors/collaborators endpoint, which runs a LIVE GitHub-admin check
// against the caller's own GitHub identity — the caller must be a current
// admin of the upstream (org repo) or its owner (user repo). Run it as
// yourself, not via a break-glass service-account token.
//
// Grant/revoke used to live here too, but the server sunset those endpoints
// (mirror collaboration is now managed upstream on GitHub and reconciled
// into SpiceDB), so only the read path remains.
//
// The cluster-host is an optional trailing positional, defaulting to
// defaultClusterHost. A grant is per-cell (a mirror is a per-cluster native
// repo with its own SpiceDB grant), so when a repo is mirrored on more than
// one cluster, pass the cluster explicitly to target the right placement.
func newRepoMirrorCollaboratorsCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "collaborators",
		Short: "List the users with access to a mirror (live GitHub-admin gated)",
	}
	cmd.AddCommand(newRepoMirrorCollaboratorsListCmd())
	return cmd
}

func newRepoMirrorCollaboratorsListCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "list <github-url> [cluster-host]",
		Short: "List the users with access to a mirror",
		Long: "Lists the principals that can pull the mirror of <github-url> on " +
			"the target cluster, with their reader/writer role resolved from the " +
			"control plane. The caller must be a live GitHub admin of the upstream " +
			"(org repo) or its owner (user repo). The cluster-host defaults to " +
			defaultClusterHost + " when omitted.",
		Example: "  entire repo mirror collaborators list github.com/acme/widget",
		Args:    cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			owner, repo, err := parseGitHubURL(args[0])
			if err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid <github-url>: %w", err)
			}
			clusterHost := clusterArgAt(args, 1)
			if err := validateClusterHost(clusterHost); err != nil {
				cmd.SilenceUsage = true
				return fmt.Errorf("invalid [cluster-host]: %w", err)
			}
			return runCoreListForCluster(cmd, clusterHost, mirrorCollaboratorColumns, mirrorCollaboratorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.MirrorCollaborator, error) {
				out, err := c.ListMirrorCollaborators(ctx, coreapi.ListMirrorCollaboratorsParams{
					Provider:    coreapi.ListMirrorCollaboratorsProviderGithub,
					Owner:       owner,
					Repo:        repo,
					ClusterHost: clusterHost,
				})
				if err != nil {
					return nil, err
				}
				return out.Collaborators, nil
			})
		},
	}
}

