```

`grant.go` `revokeGrant` — same treatment (no-op text unchanged so the "nothing to revoke" contract holds; success gains the ✓):

```go
func revokeGrant(cmd *cobra.Command, verb, subject string, revoke func() error) error {
	if err := revoke(); err != nil {
		if isCoreNotFound(err) {
			fmt.Fprintf(cmd.OutOrStdout(), "%s: no such grant; nothing to revoke\n", subject)
			return nil
		}
		return err
	}
	fmt.Fprintf(cmd.OutOrStdout(), "✓ %s %s\n", verb, subject)
	return nil
}
```

`repo_mirror.go` mirror remove — replace the `cmd.Printf` line:

